// Все идентификаторы — id из assumptions. Месяцы t = 1..24 (t = 1 — март 2027). W = [0.6, 0.25, 0.15] — как 90-дневная конверсия распределяется по 3 месяцам.
// Платформы: D = Mac DMG (Paddle), M = Mac App Store, I = iPhone/iPad, T = ТВ.
const W = [0.6, 0.25, 0.15];
const isPack = t => t > paid_month && (t - paid_month) % pack_every === 0;
const ev = t => t < 1 ? 0 : burst_free*(t===1) + burst_paid*(t===paid_month) + burst_y2*(t===13) + burst_pack*(isPack(t)?1:0) + viral*(t===7);
const unitNet = (price, pl) => { const g = price*(1 - vat_drag);
  return pl==='D' ? g - fee_paddle_pct*price - fee_paddle_fix : pl==='T' ? g*(1 - fee_tv) : g*(1 - fee_apple); };
const mult = {D:1, M:1, I:m_ios, T:m_tv};
let cohorts = [], poolB = {D:0,M:0,I:0,T:0}, poolN = {D:0,M:0,I:0,T:0}, b2bNew = [0], cum = 0, rows = [];
for (let t = 1; t <= 24; t++) {
  // 1) отток: активные не-покупатели и пулы покупателей
  for (const c of cohorts) c.nb *= ret;
  for (const k in poolB) { poolB[k] *= bret; poolN[k] *= bret; }
  // 2) загрузки: события (75% в месяц события, 25% в следующий) + органика + соцсети
  const org = t <= 12 ? org_m1 + (org_m12 - org_m1)*(t-1)/11 : org_m12 + (org_m24 - org_m12)*(t-12)/12;
  const other = 0.75*ev(t) + 0.25*ev(t-1) + org + social_mo;
  const masLive = mas_on === 1 && t >= mas_start;
  const masSearch = !masLive ? 0 : (t <= 12 ? mas_a + (mas_m12 - mas_a)*(t - mas_start)/Math.max(1, 12 - mas_start) : mas_m12 + (mas_m24 - mas_m12)*(t-12)/12);
  const dl = {
    D: masLive ? (1 - mas_share)*other : other,
    M: masLive ? masSearch + mas_share*other + ads_mo/cpi : 0,
    I: (ios_start > 0 && t >= ios_start) ? ios_a + (ios_b - ios_a)*Math.min(1, (t - ios_start)/11) + (t === ios_start ? ios_spike : 0) : 0,
    T: (tv_start > 0 && t >= tv_start) ? tv_a + (tv_b - tv_a)*Math.min(1, (t - tv_start)/11) + (t === tv_start ? tv_spike : 0) : 0 };
  for (const pl in dl) if (dl[pl] > 0) { const a0 = dl[pl]*(pl === 'D' ? act_dmg : act_store);
    cohorts.push({pl, m: t, a0, nb: a0, early: t < paid_month, base0: 0}); }
  // 3) первые покупки (только с paid_month)
  const newB = {D:0,M:0,I:0,T:0};
  if (t >= paid_month) for (const c of cohorts) {
    const mu = mult[c.pl]*(1 + lift);
    const tail = c.nb*(r_tail + (isPack(t) ? p_pack : 0))*mu;
    let b;
    if (c.early) { if (t === paid_month) c.base0 = c.nb; const k = t - paid_month; b = k < 3 ? c.base0*c_old*mu*W[k] : tail; }
    else { const k = t - c.m; b = k < 3 ? c.a0*c_new*mu*W[k] : tail; }
    b = Math.min(b, c.nb); c.nb -= b; newB[c.pl] += b;
  }
  // 4) выручка: микс первой покупки + повторные (новый пак для покупателей без бандла, докупка «своей рыбки»)
  const s_pack = 1 - s_bundle - s_fish;
  let gross = 0, net = 0, tx = 0, fishTx = 0, buyers = 0;
  for (const k in newB) { const B = newB[k]; buyers += B;
    let ub = B*s_bundle, up = B*s_pack, uf = B*s_fish;
    const rp = isPack(t) ? poolN[k]*x_pack : 0;
    const rf = t > paid_month ? (poolB[k] + poolN[k])*f_rep : 0;
    poolB[k] += ub; poolN[k] += up + uf; up += rp; uf += rf;
    gross += ub*p_bundle + up*p_pack_price + uf*p_fish;
    net += keep*(ub*unitNet(p_bundle,k) + up*unitNet(p_pack_price,k) + uf*unitNet(p_fish,k));
    tx += ub + up + uf; fishTx += uf; }
  // 5) B2B: новые экраны + продления через 12 мес; продажа через Paddle
  b2bNew[t] = (b2b_start > 0 && t >= b2b_start) ? b2b_new_mo : 0;
  const b2bTx = b2bNew[t] + (t > 12 ? b2b_renew*b2bNew[t-12] : 0);
  gross += b2bTx*b2b_price; net += keep*b2bTx*unitNet(b2b_price,'D'); tx += b2bTx;
  // 6) расходы и прибыль
  const cost = c_fixed_mo + c_acct_ils_mo/fx + ((t===1 || t===13) ? c_annual : 0)
    + (t === paid_month - 1 ? 3*c_art_pack : 0) + (isPack(t) ? c_art_pack : 0)
    + ((tv_start > 0 && t === tv_start) ? c_tv_dev : 0) + ((b2b_start > 0 && t === b2b_start) ? c_b2b_kit : 0)
    + keep*tx*donation_ils/fx + fx_cost*net + fishTx*c_fish_unit + ads_mo;
  const profit = net - cost; cum += profit;
  rows.push({t, downloads: dl.D + dl.M + dl.I + dl.T, buyers, b2bScreens: b2bNew[t], gross, net, net_ils: net*fx, cost, profit, profit_ils: profit*fx, cum});
}
// Итоги: 12 мес = сумма строк t=1..12, 24 мес = t=1..24 (загрузки, покупатели, net, net_ils, cost, profit).
// Безубыточность = наименьшее t, начиная с которого cum >= 0 во всех месяцах до 24 включительно; если такого нет — «не достигается за 24 мес».
// Окно сверки со старой оценкой: строки t = paid_month .. paid_month+2.
// Проверка (значения base): загрузки 9 820 / 27 945; покупатели 86 / 325; net $450 / $2 591; прибыль −$683 / +$203; безубыточность t = 23. Low: −$2 025, не достигается. High: +$38 243, t = 5.
